  "loc.enterInternetConnectionsAddress": "Angiv din internetforbindelses adresse som server (fx din MyFRITZ!-adresse) – som regel via SMS-kommando ifølge trackerens vejledning.",
  "loc.enterShopAddressesUnder": "Butiksadresser indtaster du under Lister → Redigér indkøbsliste – findes en butik flere gange, også flere filialer. Hvis nogen opholder sig dér et stykke tid, afkrydses den planlagte indkøbstur.",
