  "loc.gpsTracker": "🛰️ GPS-tracker",
  "loc.guide1": "Installér appen <b>»Traccar Client«</b> (App Store eller Google Play, gratis).",
  "loc.guide2": "Indtast i appen under <b>Device ID</b> (Device identifier):",
  "loc.guide3": "Indtast under <b>Server URL</b>:",
  "loc.guide4": "Nøjagtighed <b>Medium</b>, afstand <b>50 m</b>. Appen sender så kun, når du bevæger dig – intet, mens du står stille. Har du flere felter (interval, heartbeat), så sæt heartbeat til fra eller 0.",
  "loc.guide5": "Tillad adgang til position: <b>Altid</b>, og slå <b>Præcis position</b> til.",
  "loc.guide6": "Slå kontakten <b>Service / Tracking</b> til, og <b>lad den altid være tændt</b> – færdig. Herefter styrer du alt i pinn.: »Send permanent« til eller fra, »Send én gang« og SOS. Så længe »Send permanent« er slået fra, ser ingen din position, og pinn. optegner ingen rute.",
  "loc.guideIntro": "Uden en anden app virker »📍 Del position« direkte i pinn. – men kun mens pinn. er åben. For at positionen også når frem, når pinn. er lukket, og skærmen er låst, sender den gratis app »Traccar Client« den direkte til pinn. (ingen Traccar-server nødvendig). Det samme for iPhone og Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Denne port skal videresendes til NAS'en i FRITZ!Box, fordi trackeren forbinder fra mobilnettet.",
