  "settings.calendar.fromFamily#wg": "fra husstanden · pinn.",
  "settings.calendar.info": "Hver profil logger ind med sin egen iCloud- eller Google-konto og afkrydser kalenderne fra den: »Til mig« ses kun af din egen profil, »Familie« ses og bruges af alle i din familie. De andre ser kun, hvilken konto en familiekalender kommer fra – sløret, fx m**l@g***l.com. Begivenheder kan som sædvanligt oprettes, redigeres, flyttes og stilles i kø offline og går direkte til iCloud eller Google (og dermed til telefonen). Synkronisering hvert 15. minut eller med »Opdatér nu«. Uden en konto virker også en kalender kun på din pinn.-server. Påmindelser og daglig oversigt via push: private begivenheder kun til dig.",
