  "settings.outlook.intro": "Hver søndag fra kl. 18 kommer ugeforhåndsvisningen med alt vigtigt for familien i den kommende uge, og på månedens sidste dag fra kl. 18 udsigten over næste måneds økonomi. Begge vises én gang som en meddelelse øverst og som en push-besked – du kan åbne dem igen her når som helst.",
  "settings.outlook.intro#wg": "Hver søndag fra kl. 18 kommer ugeforhåndsvisningen med alt vigtigt for husstanden i den kommende uge, og på månedens sidste dag fra kl. 18 udsigten over næste måneds økonomi. Begge vises én gang som en meddelelse øverst og som en push-besked – du kan åbne dem igen her når som helst.",
  "settings.outlook.introYear": "Den 28. december fra kl. 18 følger årsoverblikket: årets udgifter, lavede måltider og rejser. Det forbliver synligt til den 10. januar og kan åbnes her når som helst.",
