  "voice.widgetIos3": "Tryk længe på startskærmen → <b>+</b> → <b>Scriptable</b> → vælg en størrelse → tryk på widgetten → vælg <b>pinn</b> under »Script«. iOS opdaterer den cirka hvert 15. minut.",
  "voice.widgetIosTitle": "iPhone-widget med Scriptable",
  "voice.widgetNeedOne": "Afkryds mindst ét punkt.",
  "voice.widgetNote": "Som med Siri skal iPhone kunne nå pinn. (hjemmenetværk eller VPN). Linket virker som en adgangskode – del det ikke.",
  "voice.widgetPick": "Hvad skal widgetten vise? Afkryds, og kopiér så scriptet – ét script pr. widget.",
  "voice.widgetQuickCopy": "🔗 Kopiér hurtigadgangs-script",
  "voice.widgetQuickHint": "Hurtig adgang: en widget med tre knapper – lister, økonomi (med dit valutategn) og opgaver. Et tryk åbner den side af pinn. i Safari, ikke i den installerede app, så log ind dér én gang.",
  "voice.widgetScriptCopied": "Script kopieret.",
  "voice.widgetTasks": "Opgaver (uden husholdning)",
  "voice.widgetTick": "I den mellemstore og store widget trykker du på en opgave for at afkrydse den – den afkrydses også i pinn. iOS åbner kortvarigt Scriptable til det.",
  "voice.widgetTitle": "📲 Widgets og ⌚ Apple Watch",
  "voice.widgetViews": "Anden visning: Erstat <code>ansicht=heute</code> i linket med <code>morgen</code>, <code>einkauf</code> eller <code>alles</code>.",
  "voice.widgetWatch1": "I appen <b>Genveje</b> på iPhone opretter du en ny genvej og tilføjer handlingen <b>»Hent indholdet af URL«</b>.",
  "voice.widgetWatch2": "Tryk her på »Kopiér link til genvejen«, og indsæt det som URL (metode GET).",
  "voice.widgetWatch3": "Tilføj handlingen <b>»Vis resultat«</b> (eller »Tal tekst«) med »Indholdet af URL«.",
  "voice.widgetWatch4": "Tryk på <b>ⓘ</b>, slå <b>Vis på Apple Watch</b> til, og navngiv genvejen fx <b>pinn i dag</b>. På uret starter du den i appen Genveje eller siger »Hey Siri, pinn i dag«.",
  "voice.widgetWatchTitle": "Apple Watch med en genvej",
